tr.td:
---Machining centres that perform 2 or more of the following:
	(a)	bending;
	(b)	assembling;
	(c)	drilling;
	(d)	morticing;
	(e)	splitting;
	(f)	slicing;
	(g)	paring

---Machining centres that perform 2 or more of the following:
	(a)	sawing;
	(b)	planing;
	(c)	milling;
	(d)	moulding (by cutting);
	(e)	grinding;
	(f)	sanding;
	(g)	polishing
